/**
 * DZML preview runtime (generated by dayz-layout-tools — do not edit by hand).
 */
(function () {
  'use strict';

  // ── dz-* class → inline style (fallback for arbitrary values) ──
  function resolveClass(el, cls) {
    if (!cls || cls.indexOf('dz-') !== 0) return;
    var body = cls.substring(3);
    if (body.indexOf('xy-') === 0) {
      var p = splitPair(body.substring(3));
      if (p) { el.style.left = toCSS(p[0]); el.style.top = toCSS(p[1]); }
      return;
    }
    if (body === 'wh-full') { el.style.width = '100%'; el.style.height = '100%'; return; }
    if (body.indexOf('wh-') === 0) {
      var q = splitPair(body.substring(3));
      if (q) { el.style.width = toCSS(q[0]); el.style.height = toCSS(q[1]); }
      return;
    }
    if (body.indexOf('c-') === 0) {
      // dz-c is the widget "color": background for panels, but the TEXT color for
      // text widgets (matches in-game, where a TextWidget's color = the glyph color).
      var col = hexToCSS(body.substring(2));
      var dz = el.getAttribute && el.getAttribute('data-dz');
      if (dz === 'text' || dz === 'richtext' || dz === 'multitext') {
        el.style.color = col; el.style.backgroundColor = 'transparent';
      } else {
        el.style.backgroundColor = col;
      }
      return;
    }
    if (body.indexOf('tc-') === 0) { el.style.color = hexToCSS(body.substring(3)); return; }
  }
  function splitPair(str) {
    for (var i = 0; i < str.length; i++) {
      if (str[i] === '-') {
        var l = str.substring(0, i), r = str.substring(i + 1);
        if (l.length && r.length) return [l, r];
      }
    }
    return null;
  }
  function toCSS(v) {
    if (v.slice(-2) === 'px') return v;
    var n = parseFloat(v);
    return isNaN(n) ? v : n + '%';
  }
  function hexToCSS(hex) {
    if (hex.length === 2) { var v = parseInt(hex, 16); return 'rgb(' + v + ',' + v + ',' + v + ')'; }
    if (hex.length <= 6) return '#' + hex.padEnd(6, hex);
    if (hex.length === 8) {
      var r = parseInt(hex.substring(0, 2), 16), g = parseInt(hex.substring(2, 4), 16),
          b = parseInt(hex.substring(4, 6), 16), a = (parseInt(hex.substring(6, 8), 16) / 255).toFixed(3);
      return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
    }
    return '#' + hex;
  }
  function resolveClasses(root) {
    var els = root.querySelectorAll ? root.querySelectorAll('[data-dz]') : [];
    if (root.getAttribute && root.getAttribute('data-dz')) applyEl(root);
    for (var i = 0; i < els.length; i++) applyEl(els[i]);
  }
  function applyEl(el) {
    var cs = (el.getAttribute('class') || '').split(/\s+/);
    for (var i = 0; i < cs.length; i++) resolveClass(el, cs[i]);
  }

  // ── injected context ──
  var MANIFEST = window.__DZML_MANIFEST__ || null;
  var NAVMAP = window.__DZML_NAVMAP__ || {};
  var STRINGS = window.__DZML_STRINGS__ || {};
  var DATA = window.__DZML_DATA__ || {};
  var VIEW = 'list'; // 'list' | 'grid' — toggled by [data-view-toggle]

  // ── selector → page source ──
  // Inline templates win (bundle); else manifest path fetch (serve).
  function inlinePage(selector) {
    var t = document.querySelector('template[data-page="' + cssEscape(selector) + '"]');
    return t ? t : null;
  }
  function cssEscape(s) { return String(s).replace(/"/g, '\\"'); }

  function manifestFile(selector) {
    if (MANIFEST && MANIFEST[selector]) return MANIFEST[selector];
    // Convention fallback: tx-catalog-page → CatalogPageView.html (best effort)
    var parts = String(selector).split('-');
    if (parts.length >= 2) parts.shift();
    var name = parts.map(function (p) { return p.charAt(0).toUpperCase() + p.slice(1); }).join('');
    return name + 'View.html';
  }

  // Over the dev server (dzml serve) the gui dir is the web root, so manifest,
  // navmap, strings and manifest page paths are gui-root-relative. Resolve them
  // root-absolute so subpages (e.g. /PurchasePage/Foo.html) load nested
  // data-component hosts instead of fetching against their own subdir (404).
  // file:// (bundle) keeps relative — bundles inline templates and never fetch.
  function abs(p) {
    if (!p || p.charAt(0) === '/' || /^https?:/.test(p)) return p;
    return (location.protocol === 'file:') ? p : '/' + p;
  }

  var fetchCache = {};
  function fetchPage(file) {
    file = abs(file);
    if (fetchCache[file]) return fetchCache[file];
    fetchCache[file] = fetch(file).then(function (r) {
      if (!r.ok) throw new Error(r.status + ' ' + file);
      return r.text();
    }).then(function (html) {
      var doc = new DOMParser().parseFromString(html, 'text/html');
      var frag = document.createDocumentFragment();
      Array.prototype.slice.call(doc.body.children).forEach(function (el) {
        if (el.getAttribute && el.getAttribute('data-dz')) frag.appendChild(el.cloneNode(true));
      });
      return frag;
    });
    return fetchCache[file];
  }

  // Resolve a selector to a DocumentFragment (Promise).
  function getPageFragment(selector) {
    return getComponentFragment(selector).catch(function (e) {
      console.warn('[dzml] page load failed: ' + selector, e);
      var f = document.createDocumentFragment();
      var d = document.createElement('div');
      d.style.cssText = 'color:#888;padding:20px;text-align:center;font:13px sans-serif';
      d.textContent = 'Page not found: ' + selector + ' (' + manifestFile(selector) + ')';
      f.appendChild(d);
      return f;
    });
  }

  function fragFromEl(el) {
    var frag = document.createDocumentFragment();
    var kids = el.content ? el.content.children : el.children;
    Array.prototype.slice.call(kids).forEach(function (k) { frag.appendChild(k.cloneNode(true)); });
    return frag;
  }

  // Resolve any manifest component id (page OR foreach template) to a fragment.
  // Inline templates/pages win (bundle); else fetch the manifest file (serve).
  function getComponentFragment(id) {
    var t = inlineTemplate(id) || inlinePage(id);
    if (t) return Promise.resolve(fragFromEl(t));
    return fetchPage(manifestFile(id));
  }

  function loadInto(container, selector) {
    // Don't force position:relative — every [data-dz] host is already position:absolute
    // (a valid containing block for its loaded absolute children). Forcing relative puts
    // the host back into normal flow, so a dz-xy host (e.g. the view-toggle) renders
    // offset by its own top/left %. Only promote a genuinely static container.
    if (getComputedStyle(container).position === 'static') container.style.position = 'relative';
    container.setAttribute('data-current', selector);
    return getPageFragment(selector).then(function (frag) {
      container.innerHTML = '';
      container.appendChild(frag.cloneNode(true));
      hydrate(container);
    });
  }

  // ── ForEach: clone the row template (manifest component) into data-foreach containers ──
  function inlineTemplate(id) { return document.querySelector('template[data-template-id="' + cssEscape(id) + '"]'); }
  function sampleCount(c) {
    var cols = ((c.getAttribute('class') || '').match(/dz-cols-(\d+)/) || [])[1];
    var sc = c.getAttribute('data-sample-count');
    return sc != null ? (parseInt(sc, 10) || 0) : Math.max(3, (parseInt(cols, 10) || 1) * 2);
  }
  // Apply the current list/grid VIEW to an [data-itemview] grid: pick template +
  // column count. dz-cols-* is pure CSS, so swapping the class is enough.
  function applyView(g) {
    if (!g.hasAttribute('data-itemview')) return;
    var tpl = g.getAttribute(VIEW === 'grid' ? 'data-tpl-grid' : 'data-tpl-list');
    if (tpl) g.setAttribute('data-template', tpl);
    var cols = VIEW === 'grid' ? (g.getAttribute('data-cols-grid') || '3') : '1';
    var cls = (g.getAttribute('class') || '').replace(/\bdz-cols-\d+\b/g, '').replace(/\s+/g, ' ').trim();
    g.setAttribute('class', cls + ' dz-cols-' + cols);
  }

  // Clone N sample rows of the foreach template into container c (Promise).
  function populateForEach(c) {
    if (c.__dzPopulated) return Promise.resolve();
    c.__dzPopulated = true;
    applyView(c);
    var count = sampleCount(c);
    if (count <= 0) return Promise.resolve();
    return getComponentFragment(c.getAttribute('data-template')).then(function (frag) {
      for (var i = 0; i < count; i++) {
        var clone = frag.cloneNode(true);
        var nodes = Array.prototype.slice.call(clone.childNodes); // append empties the fragment
        c.appendChild(clone);
        nodes.forEach(function (n) { if (n.nodeType === 1) hydrate(n); });
      }
    }).catch(function () {});
  }
  function hydrateForEach(root) {
    var containers = root.querySelectorAll ? root.querySelectorAll('[data-foreach][data-template]') : [];
    Array.prototype.slice.call(containers).forEach(function (c) {
      if (c.__dzForEach) return; c.__dzForEach = true;
      // Collapsible lists stay hidden + unpopulated until a data-expands trigger fires.
      if (c.getAttribute('data-collapsed') === '1') { c.style.display = 'none'; return; }
      populateForEach(c);
    });
  }

  // Click-to-expand: a trigger with data-expands="<grid data-name>" toggles a
  // collapsed foreach in its card, populating it lazily and growing the card.
  function toggleExpand(trigger) {
    var card = trigger.closest('[data-dz="panel"]');
    if (!card) return;
    // A card may hold two view-containers (list + tiles); operate on all collapsibles.
    var grids = Array.prototype.slice.call(card.querySelectorAll('[data-foreach][data-collapsed]'));
    if (!grids.length) return;
    if (card.__dzCollapsedH == null) card.__dzCollapsedH = card.style.height || (card.offsetHeight + 'px');
    var headPx = parseFloat(card.__dzCollapsedH) || 54;
    if (card.__dzExpanded) {
      card.__dzExpanded = false;
      grids.forEach(function (g) { g.style.display = 'none'; g.__dzOpen = false; });
      card.style.height = card.__dzCollapsedH;
    } else {
      card.__dzExpanded = true;
      Promise.all(grids.map(function (g) { return populateForEach(g); })).then(function () {
        applyTwoContainer(card);            // show only the active-view container
        var open = card.querySelector('[data-foreach]:not([style*="display: none"])') || grids[0];
        card.style.height = (headPx + open.scrollHeight + 6) + 'px';
      });
    }
  }

  // Show/hide the two-container (list rows vs grid tiles) variants per current VIEW.
  // Mirrors the in-game TraderXViewModeBinder (show one container, hide the other).
  function applyTwoContainer(root) {
    var scope = root || document;
    var grid = VIEW === 'grid';
    var lists = scope.querySelectorAll ? scope.querySelectorAll('[data-viewlist]') : [];
    Array.prototype.slice.call(lists).forEach(function (el) { el.style.display = grid ? 'none' : ''; });
    var grids = scope.querySelectorAll ? scope.querySelectorAll('[data-viewgrid]') : [];
    Array.prototype.slice.call(grids).forEach(function (el) { el.style.display = grid ? '' : 'none'; });
    // TraderX two-container convention: data-name ending GridList / GridTiles
    // (mirrors in-game TraderXViewModeBinder which toggles named widgets).
    var named = scope.querySelectorAll ? scope.querySelectorAll('[data-name$="GridList"],[data-name$="GridTiles"]') : [];
    Array.prototype.slice.call(named).forEach(function (el) {
      var isTiles = /GridTiles$/.test(el.getAttribute('data-name') || '');
      el.style.display = (grid === isTiles) ? '' : 'none';
    });
    syncViewToggleWidgets(scope);
  }

  // Sync the tx-view-toggle button widgets (label + icon swap) to current VIEW.
  // Shows the icon/label of the mode you can switch TO, matching in-game UpdateIcon().
  function syncViewToggleWidgets(scope) {
    scope = scope || document;
    var grid = VIEW === 'grid';
    var q = function (sel) { return scope.querySelectorAll ? Array.prototype.slice.call(scope.querySelectorAll(sel)) : []; };
    q('[data-name="viewLabel"]').forEach(function (el) { el.textContent = grid ? 'List' : 'Grid'; });
    // Toggle the dz-hidden CLASS (it is display:none !important, so style.display can't beat it).
    q('[data-name="gridIcon"]').forEach(function (el) { el.classList.toggle('dz-hidden', grid); });
    q('[data-name="listIcon"]').forEach(function (el) { el.classList.toggle('dz-hidden', !grid); });
    q('[data-view-label]').forEach(function (el) { el.textContent = grid ? '▦ Grid' : '▤ List'; });
  }

  // Toggle list ↔ grid view for every [data-itemview] grid on the page.
  function toggleView() {
    VIEW = VIEW === 'grid' ? 'list' : 'grid';
    applyTwoContainer(document);
    Array.prototype.slice.call(document.querySelectorAll('[data-itemview]')).forEach(function (g) {
      var wasPopulated = g.__dzPopulated;
      g.innerHTML = '';
      g.__dzPopulated = false;
      applyView(g);
      if (wasPopulated) {
        populateForEach(g).then(function () {
          var card = g.closest('[data-dz="panel"]');
          if (card && g.__dzOpen && card.__dzCollapsedH != null) {
            card.style.height = (parseFloat(card.__dzCollapsedH) + g.scrollHeight + 6) + 'px';
          }
        });
      }
    });
    // reflect state on the toggle button(s): label + icon swap
    syncViewToggleWidgets(document);
  }

  // ── data-bind {{ expr }} + #loc ──
  function resolveBindings(root, ctx) {
    var loc = function (s) {
      return String(s).replace(/#([a-zA-Z0-9_]+)/g, function (m, k) { return STRINGS[k] != null ? STRINGS[k] : m; });
    };
    var bound = root.querySelectorAll ? root.querySelectorAll('[data-bind]') : [];
    Array.prototype.slice.call(bound).forEach(function (el) {
      var expr = (el.getAttribute('data-bind') || '').replace(/[{}]/g, '').trim().split('|')[0].trim();
      var val = ctx && ctx[expr] != null ? ctx[expr] : null;
      if (val != null) el.textContent = val;
    });
    // localize static text nodes containing #keys
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
    var n; var todo = [];
    while ((n = walker.nextNode())) { if (n.nodeValue && n.nodeValue.indexOf('#') !== -1) todo.push(n); }
    todo.forEach(function (t) { t.nodeValue = loc(t.nodeValue); });
  }

  // ── navigation wiring ──
  function setNavActive(selector) {
    var btns = document.querySelectorAll('[data-nav-target],[data-nav-resolved]');
    Array.prototype.slice.call(btns).forEach(function (b) {
      var t = b.getAttribute('data-nav-target') || b.getAttribute('data-nav-resolved');
      b.classList.toggle('dz-active', t === selector);
    });
  }
  function navTargetFor(el) {
    if (el.getAttribute('data-nav-target')) return el.getAttribute('data-nav-target');
    var h = el.getAttribute('data-on-click');
    if (h && NAVMAP[h]) return NAVMAP[h];
    return null;
  }
  function wireNav(root) {
    var clickers = root.querySelectorAll ? root.querySelectorAll('[data-nav-target],[data-on-click],[data-expands],[data-view-toggle]') : [];
    Array.prototype.slice.call(clickers).forEach(function (el) {
      if (el.__dzWired) return; el.__dzWired = true;
      var resolved = navTargetFor(el);
      if (resolved && !el.getAttribute('data-nav-target')) el.setAttribute('data-nav-resolved', resolved);
      el.addEventListener('click', function () {
        var target = navTargetFor(el);
        if (target) {
          var container = document.querySelector('[data-component]');
          if (container) { loadInto(container, target); setNavActive(target); }
        } else if (el.getAttribute('data-expands')) {
          toggleExpand(el);
        } else if (el.getAttribute('data-view-toggle') != null || el.getAttribute('data-on-click') === 'OnViewToggleClick') {
          toggleView();
        } else {
          var h = el.getAttribute('data-on-click');
          if (h) console.log('[dzml] ' + h + '()');
          el.style.opacity = '0.7'; setTimeout(function () { el.style.opacity = ''; }, 150);
        }
      });
    });
  }

  // Hydrate a freshly-inserted subtree: classes, foreach, bindings, nested nav.
  function hydrate(root) {
    resolveClasses(root);
    hydrateForEach(root);
    var sel = root.getAttribute && root.getAttribute('data-current');
    resolveBindings(root, (DATA[sel] && DATA[sel].bind) || DATA['*'] || null);
    applyTwoContainer(root);
    wireNav(root);
    // nested dynamic containers inside the loaded page
    var nested = root.querySelectorAll ? root.querySelectorAll('[data-component]') : [];
    Array.prototype.slice.call(nested).forEach(function (c) {
      if (c.__dzInit) return; c.__dzInit = true;
      initContainer(c);
    });
  }

  function defaultSelectorFor(container) {
    // Explicit preview default wins (lets data-component stay a {{ binding }} for in-game).
    // "none" = start empty (e.g. a modal host that's only filled when opened).
    var dft = container.getAttribute('data-default-page');
    if (dft) return dft === 'none' ? null : dft;
    var raw = container.getAttribute('data-component') || '';
    var clean = raw.replace(/[{}]/g, '').trim();
    // If data-component is a concrete selector (not a {{ binding }}), use it.
    if (clean && clean.indexOf(' ') === -1 && (!MANIFEST || MANIFEST[clean] || inlinePage(clean))) return clean;
    // Else first nav target on the page.
    var firstNav = document.querySelector('[data-nav-target]');
    if (firstNav) return firstNav.getAttribute('data-nav-target');
    // Else first manifest entry / inline page.
    if (MANIFEST) { var k = Object.keys(MANIFEST)[0]; if (k) return k; }
    var anyPage = document.querySelector('template[data-page]');
    return anyPage ? anyPage.getAttribute('data-page') : null;
  }

  function initContainer(container) {
    var sel = defaultSelectorFor(container);
    if (sel) { loadInto(container, sel); setNavActive(sel); }
  }

  function maybeFetchManifest() {
    var jobs = [];
    if (!MANIFEST) {
      jobs.push(fetch(abs('components.manifest.json')).then(function (r) { return r.ok ? r.json() : null; })
        .then(function (j) { if (j) MANIFEST = j.components || j; }).catch(function () {}));
    }
    if (!Object.keys(STRINGS).length) {
      jobs.push(fetch(abs('_fixtures/strings.json')).then(function (r) { return r.ok ? r.json() : fetch(abs('strings.json')).then(function (r2) { return r2.ok ? r2.json() : null; }); })
        .then(function (j) { if (j) STRINGS = j; }).catch(function () {}));
    }
    if (!Object.keys(NAVMAP).length) {
      jobs.push(fetch(abs('_fixtures/navmap.json')).then(function (r) { return r.ok ? r.json() : null; })
        .then(function (j) { if (j) NAVMAP = j; }).catch(function () {}));
    }
    return Promise.all(jobs);
  }

  function init() {
    resolveClasses(document);
    hydrateForEach(document);
    resolveBindings(document, DATA['*'] || null);
    applyTwoContainer(document);
    wireNav(document);
    maybeFetchManifest().then(function () {
      resolveBindings(document, DATA['*'] || null); // re-localise shell once strings are loaded
      var containers = document.querySelectorAll('[data-component]');
      Array.prototype.slice.call(containers).forEach(function (c) {
        if (c.__dzInit) return; c.__dzInit = true; initContainer(c);
      });
    });
    if (window.__DZML_LIVE__) connectLiveReload();
  }

  function connectLiveReload() {
    try {
      var es = new EventSource('/__dzml_reload');
      es.onmessage = function () { location.reload(); };
    } catch (e) { /* no server */ }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
